import { test, expect } from '@playwright/test';

test.describe('Table Filter by Search Input', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the table page
    await page.goto('http://localhost:3000/table');

    // Wait for the table to be visible
    await page.getByRole('table').waitFor({ state: 'visible' });
  });

  test('should filter table rows when typing in search input', async ({ page }) => {
    // Get the search input field
    const searchInput = page.getByLabel('Search');

    // Verify search input is visible
    await expect(searchInput).toBeVisible();

    // Get all table rows before filtering
    const tableRows = page.getByRole('row');
    const initialRowCount = await tableRows.count();

    // Verify we have rows to filter
    expect(initialRowCount).toBeGreaterThan(1);

    // Type in the search input
    await searchInput.fill('John');

    // Wait for the table to update
    await page.waitForTimeout(500);

    // Get filtered table rows
    const filteredRows = page.getByRole('row');
    const filteredRowCount = await filteredRows.count();

    // Verify that rows have been filtered
    expect(filteredRowCount).toBeLessThan(initialRowCount);

    // Verify that visible rows contain the search term
    const visibleRows = await filteredRows.all();
    for (const row of visibleRows) {
      const rowText = await row.textContent();
      expect(rowText?.toLowerCase()).toContain('john');
    }
  });

  test('should show no results when search term does not match any rows', async ({ page }) => {
    // Get the search input field
    const searchInput = page.getByLabel('Search');

    // Type a search term that should not match any rows
    await searchInput.fill('NONEXISTENTVALUE12345');

    // Wait for the table to update
    await page.waitForTimeout(500);

    // Check for no results message or empty table body
    const noResultsMessage = page.getByText(/no results|no data|no matching/i);
    const tableBody = page.getByRole('rowgroup').nth(1);

    // Either we see a no results message or the table body is empty
    const hasNoResultsMessage = await noResultsMessage.isVisible().catch(() => false);
    const tableBodyRows = tableBody.getByRole('row');
    const bodyRowCount = await tableBodyRows.count();

    expect(hasNoResultsMessage || bodyRowCount === 0).toBeTruthy();
  });

  test('should restore all rows when clearing the search input', async ({ page }) => {
    // Get the search input field
    const searchInput = page.getByLabel('Search');

    // Get initial row count
    const initialRows = page.getByRole('row');
    const initialRowCount = await initialRows.count();

    // Type in the search input to filter
    await searchInput.fill('test');
    await page.waitForTimeout(500);

    // Verify rows are filtered
    const filteredRows = page.getByRole('row');
    const filteredRowCount = await filteredRows.count();
    expect(filteredRowCount).toBeLessThanOrEqual(initialRowCount);

    // Clear the search input
    await searchInput.clear();
    await page.waitForTimeout(500);

    // Verify all rows are restored
    const restoredRows = page.getByRole('row');
    const restoredRowCount = await restoredRows.count();
    expect(restoredRowCount).toBe(initialRowCount);
  });

  test('should perform case-insensitive search', async ({ page }) => {
    // Get the search input field
    const searchInput = page.getByLabel('Search');

    // Search with lowercase
    await searchInput.fill('alice');
    await page.waitForTimeout(500);

    const lowercaseRows = page.getByRole('row');
    const lowercaseCount = await lowercaseRows.count();

    // Clear and search with uppercase
    await searchInput.clear();
    await page.waitForTimeout(300);

    await searchInput.fill('ALICE');
    await page.waitForTimeout(500);

    const uppercaseRows = page.getByRole('row');
    const uppercaseCount = await uppercaseRows.count();

    // Both searches should return the same number of results
    expect(lowercaseCount).toBe(uppercaseCount);
  });

  test('should filter table with special characters in search term', async ({ page }) => {
    // Get the search input field
    const searchInput = page.getByLabel('Search');

    // Get initial row count
    const initialRows = page.getByRole('row');
    const initialRowCount = await initialRows.count();

    // Search with special characters
    await searchInput.fill('@');
    await page.waitForTimeout(500);

    // Verify the search was processed
    const filteredRows = page.getByRole('row');
    const filteredRowCount = await filteredRows.count();

    // Should either have filtered results or show no results
    expect(filteredRowCount).toBeLessThanOrEqual(initialRowCount);
  });

  test('should maintain search filter when table updates', async ({ page }) => {
    // Get the search input field
    const searchInput = page.getByLabel('Search');

    // Type in the search input
    await searchInput.fill('data');
    await page.waitForTimeout(500);

    // Get filtered row count
    const filteredRows = page.getByRole('row');
    const filteredRowCount = await filteredRows.count();

    // Verify search input still contains the search term
    const inputValue = await searchInput.inputValue();
    expect(inputValue).toBe('data');

    // Verify rows are still filtered
    expect(filteredRowCount).toBeGreaterThan(0);
  });
});
